function commit(data, title, desc) {
  if (editingId) {
    const it = items.find(x => x.id === editingId);
    if (it) { it.title = title; it.desc = desc; }
    reviewMount.innerHTML = ''; editingId = null;
    redraw(); flash(editingId);
    const el = it ? document.getElementById('item-' + it.id) : null;
    if (el) flashEl(el);
  } else {
    const it = { id: seq++, key: data.key, url: data.url, host: data.host, title: title, desc: desc, hasPreview: true };
    items.unshift(it);
    reviewMount.innerHTML = '';
    redraw();
    hint.className = 'hint'; hint.textContent = 'Saved.';
    setTimeout(() => { if (hint.textContent === 'Saved.') hint.textContent = ''; }, 1800);
  }
  input.value = ''; input.focus();
}

