function openReview(data, isEdit) {
  reviewMount.innerHTML = '';
  editingId = isEdit ? data.id : null;
  const host = data.host;
  const panel = document.createElement('div');
  panel.className = 'review';
  panel.innerHTML =
    '<div class="cap">' + (isEdit ? 'Edit bookmark' : 'Review before saving') + '</div>' +
    '<div class="source" id="src"></div>' +
    '<div class="field"><label>Title</label><input id="fTitle" type="text" /></div>' +
    '<div class="field"><label>Description</label><textarea id="fDesc" rows="2" placeholder="A short note about this page"></textarea></div>' +
    '<div class="actions">' +
      '<button class="btn-primary" id="doSave">' + (isEdit ? 'Save changes' : 'Save bookmark') + '</button>' +
      '<button class="btn-ghost" id="doCancel">Cancel</button>' +
    '</div>';
  reviewMount.appendChild(panel);
  const cap = panel.querySelector('.cap');
  const pv = previewEl(host, data.title || host);
  cap.insertAdjacentElement('afterend', pv);
  const note = document.createElement('div');
  note.className = 'pv-note';
  note.textContent = 'Preview picture gathered from the page (stand-in shown here).';
  pv.insertAdjacentElement('afterend', note);
  const src = panel.querySelector('#src');
  src.appendChild(favEl(host));
  const s = document.createElement('span');
  s.textContent = host + '  ·  ' + data.url;
  src.appendChild(s);
  const fTitle = panel.querySelector('#fTitle');
  const fDesc = panel.querySelector('#fDesc');
  fTitle.value = data.title || '';
  fDesc.value = data.desc || '';
  fTitle.focus(); fTitle.select();

  panel.querySelector('#doCancel').addEventListener('click', function () {
    reviewMount.innerHTML = ''; editingId = null; input.focus();
  });
  panel.querySelector('#doSave').addEventListener('click', function () {
    commit(data, fTitle.value.trim() || guessTitle(new URL(data.url)), fDesc.value.trim());
  });
}

