.edit-link { background: none; border: none; color: var(--muted); font-size: 12.5px; cursor: pointer; padding: 2px 4px; }
.edit-link:hover { color: var(--accent); }

/* Tags — the client's own labels, deliberately distinct from the muted source line */
.tags { display: flex; flex-wrap: wrap; gap: 6px; margin: 2px 0 4px; }
.tag {
  display: inline-flex; align-items: center; gap: 5px; background: var(--accent-soft);
  color: var(--accent); font-size: 12px; font-weight: 500; padding: 3px 10px; border-radius: 999px;
}
.tag .x { cursor: pointer; opacity: .6; font-size: 13px; line-height: 1; }
.tag .x:hover { opacity: 1; }
.tag-input { width: 100%; border: 1px solid var(--line); border-radius: 9px; padding: 9px 11px; font: inherit; font-size: 14px; outline: none; background: #fdfdfc; }
.tag-input:focus { border-color: var(--accent); }
.tag-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.tag-chips:not(:empty) { margin-bottom: 8px; }
.tag-pick { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; }
.tag-toggle {
  border: 1px solid var(--line); background: #fff; color: var(--muted); font-size: 12px;
  padding: 4px 11px; border-radius: 999px; cursor: pointer;
}
.tag-toggle.on { background: var(--accent-soft); color: var(--accent); border-color: var(--accent-soft); font-weight: 600; }
.tag-hint { font-size: 11px; color: var(--muted); margin-top: 5px; }

