// Builds the tag-adding widget for the mode under comparison; returns a getter for the chosen tags.
function buildTagInput(mount, current) {
  mount.innerHTML = '';
  if (MODE === 'b') {
    // Comma-separated free text
    const inp = document.createElement('input');
    inp.className = 'tag-input';
    inp.placeholder = 'e.g. work, reading, ai';
    inp.value = current.join(', ');
    const hint = document.createElement('div');
    hint.className = 'tag-hint'; hint.textContent = 'Separate tags with commas.';
    mount.appendChild(inp); mount.appendChild(hint);
    return () => uniq(inp.value.split(',').map(cleanTag).filter(Boolean));
  }
  if (MODE === 'c') {
    // Pick from existing, plus add a new one
    let chosen = current.slice();
    const pick = document.createElement('div'); pick.className = 'tag-pick';
    const inp = document.createElement('input');
    inp.className = 'tag-input'; inp.placeholder = 'Add a new tag and press Enter';
    const hint = document.createElement('div');
    hint.className = 'tag-hint'; hint.textContent = 'Tap an existing tag to apply it, or type a new one.';
    function paint() {
      pick.innerHTML = '';
      uniq(allTags().concat(chosen)).forEach(function (t) {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'tag-toggle' + (chosen.includes(t) ? ' on' : '');
        b.textContent = t;
        b.addEventListener('click', function () {
          if (chosen.includes(t)) chosen = chosen.filter(x => x !== t); else chosen.push(t);
          paint();
        });
        pick.appendChild(b);
      });
      if (uniq(allTags().concat(chosen)).length === 0) {
        const em = document.createElement('span'); em.className = 'tag-hint';
        em.textContent = 'No tags yet — type one below.'; pick.appendChild(em);
      }
    }
    inp.addEventListener('keydown', function (e) {
      if (e.key === 'Enter') {
        e.preventDefault();
        const t = cleanTag(inp.value);
        if (t && !chosen.includes(t)) chosen.push(t);
        inp.value = ''; paint();
      }
    });
    mount.appendChild(pick); mount.appendChild(inp); mount.appendChild(hint);
    paint();
    return () => uniq(chosen.map(cleanTag).filter(Boolean));
  }
  // MODE 'a' (default): chips added with Enter, removable with ×
  let chips = current.slice();
  const box = document.createElement('div'); box.className = 'tag-chips';
  const inp = document.createElement('input');
  inp.className = 'tag-input'; inp.placeholder = 'Type a tag and press Enter';
  const hint = document.createElement('div');
  hint.className = 'tag-hint'; hint.textContent = 'Press Enter to add each tag; click × to remove.';
  function paint() {
    box.innerHTML = '';
    chips.forEach(function (t, i) {
      const c = document.createElement('span'); c.className = 'tag';
      c.appendChild(document.createTextNode(t));
      const x = document.createElement('span'); x.className = 'x'; x.textContent = '×';
      x.addEventListener('click', function () { chips.splice(i, 1); paint(); });
      c.appendChild(x); box.appendChild(c);
    });
  }
  inp.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.key === ',') {
      e.preventDefault();
      const t = cleanTag(inp.value);
      if (t && !chips.includes(t)) chips.push(t);
      inp.value = ''; paint();
    } else if (e.key === 'Backspace' && !inp.value && chips.length) {
      chips.pop(); paint();
    }
  });
  mount.appendChild(box); mount.appendChild(inp); mount.appendChild(hint);
  paint();
  return () => uniq(chips.map(cleanTag).filter(Boolean));
}

