function commit(data, title, desc, tags) {
  tags = tags || [];
  if (editingId) {
    const it = items.find(x => x.id === editingId);
    if (it) { it.title = title; it.desc = desc; it.tags = tags; }
    reviewMount.innerHTML = ''; editingId = null;
    redraw();
    const el = it ? document.getElementById('item-' + it.id) : null;
    if (el) flashEl(el);
  } else {
    const it = { id: seq++, key: data.key, url: data.url, host: data.host, title: title, desc: desc, tags: tags, hasPreview: true };
    items.unshift(it);
    reviewMount.innerHTML = '';
    redraw();
    hint.className = 'hint'; hint.textContent = 'Saved.';
    setTimeout(() => { if (hint.textContent === 'Saved.') hint.textContent = ''; }, 1800);
  }
  input.value = ''; input.focus();
}

function flashEl(el) {
  el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  el.classList.add('flash');
  setTimeout(() => el.classList.remove('flash'), 1600);
}

