form.addEventListener('submit', function (e) {
  e.preventDefault();
  const u = normalise(input.value);
  if (!u) { hint.className = 'hint warn'; hint.textContent = "Hmm, that doesn't look like a link yet."; return; }
  const key = keyOf(u);
  const existing = items.find(x => x.key === key);
  if (existing) {
    hint.className = 'hint warn';
