// Tag-adding interaction under comparison: a = chips, b = comma text, c = pick-from-existing
const MODE = (new URLSearchParams(location.search).get('tags') || 'c').toLowerCase();
// Note-writing interaction under comparison: md = type formatting, toolbar = buttons
const NOTE_MODE = (new URLSearchParams(location.search).get('note') || 'md').toLowerCase();

// Minimal, safe formatter for personal notes: bold, italic, bullet lists, links, line breaks.
function esc(s) { return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function renderNote(md) {
  if (!md || !md.trim()) return '';
  const lines = md.replace(/\r\n/g, '\n').split('\n');
  let html = '', listOpen = false;
  const inline = (t) => esc(t)
    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, (m, txt, url) => '<a href="' + url + '" target="_blank" rel="noopener">' + txt + '</a>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/\*([^*]+)\*/g, '<em>$1</em>');
  let para = [];
  const flushPara = () => { if (para.length) { html += '<p>' + para.join('<br>') + '</p>'; para = []; } };
  lines.forEach(function (ln) {
    if (/^\s*[-*]\s+/.test(ln)) {
      flushPara();
      if (!listOpen) { html += '<ul>'; listOpen = true; }
      html += '<li>' + inline(ln.replace(/^\s*[-*]\s+/, '')) + '</li>';
    } else if (ln.trim() === '') {
      if (listOpen) { html += '</ul>'; listOpen = false; }
      flushPara();
    } else {
      if (listOpen) { html += '</ul>'; listOpen = false; }
      para.push(inline(ln));
    }
  });
  if (listOpen) html += '</ul>';
  flushPara();
  return html;
}

