input.new_string:
  const getTags = buildTagInput(panel.querySelector('#fTags'), (data.tags || []).slice());
  const fRead = panel.querySelector('#fRead');
  fRead.checked = !!data.toRead;
  const fAddr = panel.querySelector('#fAddr');
  fAddr.value = data.url || '';
  const fNote = panel.querySelector('#fNote');
  fNote.value = data.note || '';
  const notePrev = panel.querySelector('#notePrev');
  function paintNote() {
    const h = renderNote(fNote.value);
    notePrev.innerHTML = h ? '<span class="pv-label">Preview</span><div class="note-body">' + h + '</div>' : '';
  }
  fNote.addEventListener('input', paintNote);
  paintNote();
  // Toolbar buttons (only present in the toolbar variant) wrap the selection.
  panel.querySelectorAll('.md-btn').forEach(function (btn) {
    btn.addEventListener('click', function () {
      const s = fNote.selectionStart, e = fNote.selectionEnd, v = fNote.value;
      const sel = v.slice(s, e) || (btn.dataset.md === 'list' ? 'item' : 'text');
      let out;
      if (btn.dataset.md === 'bold') out = '**' + sel + '**';
      else if (btn.dataset.md === 'italic') out = '*' + sel + '*';
      else out = (s > 0 && v[s - 1] !== '\n' ? '\n' : '') + '- ' + sel;
      fNote.value = v.slice(0, s) + out + v.slice(e);
      fNote.focus(); paintNote();
    });
  });
  fTitle.focus(); fTitle.select();

  panel.querySelector('#doCancel').addEventListener('click', function () {
    reviewMount.innerHTML = ''; editingId = null; input.focus();
  });
  panel.querySelector('#doSave').addEventListener('click', function () {
    let addr = fAddr.value.trim();
    const parsed = normalise(addr);   // keep the old address if the new one isn't usable
    commit(data, {
      address: parsed ? parsed.href : data.url,
      title: fTitle.value.trim() || guessTitle(new URL(parsed ? parsed.href : data.url)),
      desc: fDesc.value.trim(),
      note: fNote.value.trim(),
      tags: getTags(),
      toRead: fRead.checked
    });
  });
}

