input.old_string:
function commit(data, title, desc, tags, toRead) {
  tags = tags || [];
  if (editingId) {
    const it = items.find(x => x.id === editingId);
    if (it) { it.title = title; it.desc = desc; it.tags = tags; it.toRead = !!toRead; it.updated = Date.now(); }
    reviewMount.innerHTML = ''; editingId = null;
    redraw();
    const el = it ? document.getElementById('item-' + it.id) : null;
    if (el) flashEl(el);
  } else {
    const now = Date.now();
    const it = { id: seq++, key: data.key, url: data.url, host: data.host, title: title, desc: desc, tags: tags, hasPreview: true, archived: false, toRead: !!toRead, created: now, updated: now };
    items.unshift(it);

