      it.title = f.title; it.desc = f.desc; it.note = f.note; it.tags = tags; it.toRead = !!f.toRead;
      it.url = addrU.href; it.host = host; it.key = key; it.updated = Date.now();
    }
    reviewMount.innerHTML = ''; editingId = null;
    redraw();
    const el = it ? document.getElementById('item-' + it.id) : null;
    if (el) flashEl(el);
  } else {
    const now = Date.now();
