// ---- Bulk actions on selected bookmarks -------------------------------
let bulkTagFormOpen = false;

function bulkApply(fn) {
  let changed = false;
  items.forEach(it => { if (selected.has(it.id)) { fn(it); it.updated = Date.now(); changed = true; } });
  if (changed) redraw();   // redraw prunes selection to what stays visible
}

function renderBulkBar(visible) {
  bulkMount.innerHTML = '';
  if (selected.size === 0) { bulkTagFormOpen = false; return; }
  const bar = document.createElement('div'); bar.className = 'bulkbar';

  const r1 = document.createElement('div'); r1.className = 'bulk-row1';
  const count = document.createElement('span'); count.textContent = selected.size + ' selected'; r1.appendChild(count);
  const allSelected = visible.length > 0 && visible.every(it => selected.has(it.id));
  const selAll = document.createElement('button'); selAll.className = 'link';
  selAll.textContent = allSelected ? 'Clear selection' : ('Select all ' + visible.length + ' shown');
  selAll.addEventListener('click', function () {
    if (allSelected) selected.clear(); else visible.forEach(it => selected.add(it.id));
    redraw();
  });
  r1.appendChild(selAll);
  if (!allSelected) {
    const clr = document.createElement('button'); clr.className = 'link'; clr.textContent = 'Clear';
    clr.addEventListener('click', function () { selected.clear(); redraw(); });
    r1.appendChild(clr);
  }
  bar.appendChild(r1);

  const acts = document.createElement('div'); acts.className = 'bulk-actions';
  const mk = (label, cls, fn) => { const b = document.createElement('button'); b.className = 'bulk-btn' + (cls ? ' ' + cls : ''); b.textContent = label; b.addEventListener('click', fn); return b; };
  acts.appendChild(mk('Tag / untag…', '', function () { bulkTagFormOpen = !bulkTagFormOpen; renderBulkBar(currentVisible()); }));
  if (currentView !== 'archive') {
    acts.appendChild(mk('Mark as read', '', () => bulkApply(it => { it.toRead = false; })));
    acts.appendChild(mk('Mark as unread', '', () => bulkApply(it => { it.toRead = true; })));
    acts.appendChild(mk('Archive', '', () => bulkApply(it => { it.archived = true; })));
  } else {
    acts.appendChild(mk('Restore to collection', '', () => bulkApply(it => { it.archived = false; })));
  }
  acts.appendChild(mk('Delete', 'danger', function () { showBulkDelete(bar); }));
  bar.appendChild(acts);

  if (bulkTagFormOpen) {
    const form = document.createElement('div'); form.className = 'bulk-form';
    const inp = document.createElement('input'); inp.placeholder = 'Tag name (e.g. reading)'; inp.setAttribute('list', 'bulk-tags');
    const dl = document.createElement('datalist'); dl.id = 'bulk-tags';
    allTags().forEach(t => { const o = document.createElement('option'); o.value = t; dl.appendChild(o); });
    const apply = (mode) => {
      const t = cleanTag(inp.value); if (!t) return;
      bulkApply(it => {
        it.tags = it.tags || [];
        if (mode === 'add') { if (!it.tags.includes(t)) it.tags.push(t); }
        else it.tags = it.tags.filter(x => x !== t);
      });
    };
    const add = document.createElement('button'); add.className = 'bulk-btn'; add.textContent = 'Add to selected';
    const rem = document.createElement('button'); rem.className = 'bulk-btn'; rem.textContent = 'Remove from selected';
    add.addEventListener('click', () => apply('add'));
    rem.addEventListener('click', () => apply('remove'));
    form.appendChild(inp); form.appendChild(dl); form.appendChild(add); form.appendChild(rem);
    bar.appendChild(form);
    setTimeout(() => inp.focus(), 0);
  }

  bulkMount.appendChild(bar);
}

function showBulkDelete(bar) {
  if (bar.querySelector('.bulk-delete')) return;
  const box = document.createElement('div'); box.className = 'bulk-form bulk-delete';
  const msg = document.createElement('span'); msg.className = 'bulk-note';
  msg.textContent = 'Delete ' + selected.size + (selected.size === 1 ? ' bookmark' : ' bookmarks') + ' for good? This can’t be undone.';
  const del = document.createElement('button'); del.className = 'bulk-btn danger'; del.textContent = 'Delete permanently';
  const cancel = document.createElement('button'); cancel.className = 'bulk-btn'; cancel.textContent = 'Cancel';
  del.addEventListener('click', function () { items = items.filter(it => !selected.has(it.id)); selected.clear(); redraw(); });
  cancel.addEventListener('click', function () { box.remove(); });
  box.appendChild(msg); box.appendChild(del); box.appendChild(cancel);
  bar.appendChild(box);
}

