const bulkMount = document.getElementById('bulkMount');
const saveSearchBtn = document.getElementById('saveSearch');
const savedMount = document.getElementById('savedMount');

let savedSearches = [];   // {id, name, query, view}
let savedSeq = 1;
const viewName = v => v === 'reading' ? 'Reading list' : v === 'archive' ? 'Archive' : 'Collection';

function renderSaved() {
  // Preserve an open naming form across redraws.
  if (savedMount.querySelector('.save-form')) return;
  savedMount.innerHTML = '';
  if (savedSearches.length === 0) return;
  const strip = document.createElement('div'); strip.className = 'saved-strip';
  const lead = document.createElement('span'); lead.className = 'lead'; lead.textContent = 'Saved searches:'; strip.appendChild(lead);
  savedSearches.forEach(function (s) {
    const chip = document.createElement('span'); chip.className = 'saved-chip';
    const nm = document.createElement('span'); nm.className = 'name'; nm.textContent = s.name;
    nm.title = 'Apply: ' + (s.query || '(all)') + ' — in ' + viewName(s.view);
    nm.addEventListener('click', function () {
      currentView = s.view; search.value = s.query; redraw();
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
    const rm = document.createElement('button'); rm.className = 'rm'; rm.textContent = '×'; rm.title = 'Remove saved search';
    rm.addEventListener('click', function () { savedSearches = savedSearches.filter(x => x.id !== s.id); renderSaved(); });
    chip.appendChild(nm); chip.appendChild(rm); strip.appendChild(chip);
  });
  savedMount.appendChild(strip);
}

function openSaveForm() {
  const q = search.value.trim();
  if (!q) { hint.className = 'hint warn'; hint.textContent = 'Type a search first, then save it.'; return; }
  savedMount.innerHTML = '';
  const form = document.createElement('div'); form.className = 'save-form';
  const lbl = document.createElement('span'); lbl.className = 'lbl'; lbl.textContent = 'Save “' + q + '” in ' + viewName(currentView) + ' as:';
  const inp = document.createElement('input'); inp.value = q;
  const ok = document.createElement('button'); ok.className = 'ok'; ok.textContent = 'Save search';
  const no = document.createElement('button'); no.className = 'no'; no.textContent = 'Cancel';
  ok.addEventListener('click', function () {
    const name = inp.value.trim() || q;
    savedSearches.push({ id: savedSeq++, name: name, query: q, view: currentView });
    renderSaved();
  });
  no.addEventListener('click', function () { renderSaved(); });
  form.appendChild(lbl); form.appendChild(inp); form.appendChild(ok); form.appendChild(no);
  savedMount.appendChild(form); setTimeout(() => { inp.focus(); inp.select(); }, 0);
}

