function fmtDate(ts) {
  return new Date(ts).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}

// ---- Saved page copies (simulated in the prototype) --------------------
let openCopyId = null;   // which card's copy panel is expanded
function isPdf(url) { return /\.pdf($|[?#])/i.test(url); }
function iaUrl(url) {
  const d = new Date();
  const stamp = d.getFullYear() + String(d.getMonth() + 1).padStart(2, '0') + String(d.getDate()).padStart(2, '0') + '000000';
  return 'https://web.archive.org/web/' + stamp + '/' + url;
}
function copyPanel(it) {
  it.copies = it.copies || { local: null, ia: null };
  const wrap = document.createElement('div'); wrap.className = 'copy-panel';
  const pdf = isPdf(it.url);

  const row1 = document.createElement('div'); row1.className = 'cp-row';
  const l1 = document.createElement('span'); l1.className = 'cp-label'; l1.textContent = pdf ? 'Kept PDF' : 'Saved copy here';
  row1.appendChild(l1);
  if (it.copies.local) {
    const st = document.createElement('span'); st.className = 'cp-status';
    st.textContent = (it.copies.local.kind === 'pdf' ? 'PDF kept ' : 'Saved ') + fmtDate(it.copies.local.when) + ' · ';
    const view = document.createElement('a'); view.href = 'saved-copy-sample.html'; view.target = '_blank'; view.rel = 'noopener'; view.textContent = 'View';
    st.appendChild(view); row1.appendChild(st);
  } else {
    row1.appendChild(actBtn(pdf ? 'Keep the PDF' : 'Save a copy here', 'primary', () => { it.copies.local = { when: Date.now(), kind: pdf ? 'pdf' : 'page' }; redraw(); }));
  }

  const row2 = document.createElement('div'); row2.className = 'cp-row';
  const l2 = document.createElement('span'); l2.className = 'cp-label'; l2.textContent = 'Internet Archive';
  row2.appendChild(l2);
  if (it.copies.ia) {
    const st = document.createElement('span'); st.className = 'cp-status';
    st.textContent = 'Submitted ' + fmtDate(it.copies.ia.when) + ' · ';
    const open = document.createElement('a'); open.href = it.copies.ia.url; open.target = '_blank'; open.rel = 'noopener'; open.textContent = 'Open at archive.org';
    st.appendChild(open); row2.appendChild(st);
  } else {
    row2.appendChild(actBtn('Save to Internet Archive', '', () => { it.copies.ia = { when: Date.now(), url: iaUrl(it.url) }; redraw(); }));
  }

  const note = document.createElement('div'); note.className = 'cp-note';
  note.textContent = 'Preview only: copies are simulated here. The finished app fetches and stores the page (or the PDF) and submits the address to the Internet Archive.';

  wrap.appendChild(row1); wrap.appendChild(row2); wrap.appendChild(note);
  return wrap;
}

