let openCopyId = null;   // which card's copy panel is expanded
function isPdf(url) { return /\.pdf($|[?#])/i.test(url); }
function iaUrl(url) {
  const d = new Date();
  const stamp = d.getFullYear() + String(d.getMonth() + 1).padStart(2, '0') + String(d.getDate()).padStart(2, '0') + '000000';
  return 'https://web.archive.org/web/' + stamp + '/' + url;
}
function copyPanel(it) {
  it.copies = it.copies || { local: null, ia: null };
