    st.appendChild(view); row1.appendChild(st);
  } else {
    row1.appendChild(actBtn(pdf ? 'Keep the PDF' : 'Save a copy here', 'primary', () => { it.copies.local = { when: Date.now(), kind: pdf ? 'pdf' : 'page' }; redraw(); }));
  }

  const row2 = document.createElement('div'); row2.className = 'cp-row';
  const l2 = document.createElement('span'); l2.className = 'cp-label'; l2.textContent = 'Internet Archive';
