  } else {
    row2.appendChild(actBtn('Save to Internet Archive', '', () => { it.copies.ia = { when: Date.now(), url: iaUrl(it.url) }; redraw(); }));
  }

  const note = document.createElement('div'); note.className = 'cp-note';
  note.textContent = 'Preview only: copies are simulated here. The finished app fetches and stores the page (or the PDF) and submits the address to the Internet Archive.';

  wrap.appendChild(row1); wrap.appendChild(row2); wrap.appendChild(note);
