.head-row { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.io-btn { border: 1px solid var(--line); background: var(--card); color: var(--muted); font: inherit; font-size: 13px; padding: 7px 12px; border-radius: 9px; cursor: pointer; white-space: nowrap; }
.io-btn:hover { border-color: var(--accent); color: var(--accent); }
.io-panel { background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 18px; margin-bottom: 20px; box-shadow: 0 4px 16px rgba(0,0,0,0.05); }
.io-panel h2 { font-size: 14px; margin: 0 0 6px; }
.io-sec { padding: 12px 0; }
.io-sec + .io-sec { border-top: 1px solid var(--line); }
.io-sub { font-size: 12.5px; color: var(--muted); margin: 0 0 10px; }
.io-controls { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.io-controls button, .io-file label { border: 1px solid var(--line); background: #fff; color: var(--ink); font: inherit; font-size: 13px; padding: 7px 12px; border-radius: 9px; cursor: pointer; }
.io-controls button.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.io-controls button:hover { border-color: var(--accent); }
.io-result { margin-top: 12px; font-size: 13px; }
.io-preview-list { margin: 8px 0 0; padding: 10px 12px; background: #fbfbf9; border: 1px solid var(--line); border-radius: 9px; max-height: 180px; overflow: auto; font-size: 12.5px; }
.io-preview-list .r { padding: 3px 0; color: #4a4a44; }
.io-preview-list .r .meta { color: var(--muted); }
.io-text { width: 100%; box-sizing: border-box; margin-top: 10px; height: 150px; font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 11.5px; border: 1px solid var(--line); border-radius: 9px; padding: 10px; background: #fbfbf9; color: #333; }
.io-close { float: right; border: none; background: none; color: var(--muted); font-size: 18px; cursor: pointer; }

