search.addEventListener('input', redraw);
clearSearch.addEventListener('click', function () { search.value = ''; redraw(); search.focus(); });

// ---- Import / Export ---------------------------------------------------
const ioBtn = document.getElementById('ioBtn');
const ioMount = document.getElementById('ioMount');
let ioOpen = false;

function parseNetscape(html) {
  const doc = new DOMParser().parseFromString(html, 'text/html');
  const out = [];
  function walk(dl, path) {
    Array.from(dl.children).forEach(function (node) {
      if (node.tagName !== 'DT') return;
      const h3 = node.querySelector(':scope > h3');
      if (h3) {
        const name = h3.textContent.trim();
        const sub = node.querySelector(':scope > dl') ||
          (node.nextElementSibling && node.nextElementSibling.tagName === 'DL' ? node.nextElementSibling : null);
        if (sub) walk(sub, path.concat(name));
      } else {
        const a = node.querySelector(':scope > a');
        if (a && a.getAttribute('href')) {
          const add = a.getAttribute('add_date');
          const tagAttr = (a.getAttribute('tags') || '').split(',');
          out.push({
            url: a.getAttribute('href'),
            title: a.textContent.trim(),
            created: add ? parseInt(add, 10) * 1000 : Date.now(),
            tags: uniq(path.concat(tagAttr).map(cleanTag).filter(Boolean))
          });
        }
      }
    });
  }
  const top = doc.querySelector('dl');
  if (top) walk(top, []);
  return out;
}

function parseImport(text, filename) {
  const t = text.trim();
  if (t[0] === '{' || t[0] === '[') {
    const data = JSON.parse(t);
    const arr = Array.isArray(data) ? data : (data.bookmarks || []);
    return arr.map(r => ({ url: r.url, title: r.title || '', created: r.created || Date.now(), updated: r.updated,
      tags: uniq((r.tags || []).map(cleanTag).filter(Boolean)), desc: r.description || '', note: r.note || '',
      toRead: !!r.toRead, archived: !!r.archived }));
  }
  return parseNetscape(text);   // browser bookmarks HTML
}

function importRecords(records) {
  let added = 0, dup = 0, bad = 0;
  records.forEach(function (r) {
    const u = normalise(r.url); if (!u) { bad++; return; }
    const key = keyOf(u);
    if (items.some(x => x.key === key)) { dup++; return; }
    const now = Date.now();
    items.push({ id: seq++, key: key, url: u.href, host: u.hostname.replace(/^www\./, ''),
      title: r.title || guessTitle(u), desc: r.desc || '', note: r.note || '',
      tags: r.tags || [], hasPreview: true, archived: !!r.archived, toRead: !!r.toRead,
      created: r.created || now, updated: r.updated || r.created || now,
      copies: { local: { when: now, kind: isPdf(u.href) ? 'pdf' : 'page' }, ia: null } });
    added++;
  });
  return { added, dup, bad };
}

function exportHtml() {
  const e = s => (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  let s = '<!DOCTYPE NETSCAPE-Bookmark-file-1>\n<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">\n<TITLE>Bookmarks</TITLE>\n<H1>Bookmarks</H1>\n<DL><p>\n';
  items.forEach(function (it) {
    const dt = Math.floor((it.created || Date.now()) / 1000);
    s += '    <DT><A HREF="' + e(it.url) + '" ADD_DATE="' + dt + '"' +
      (it.tags && it.tags.length ? ' TAGS="' + e(it.tags.join(',')) + '"' : '') + '>' + e(it.title) + '</A>\n';
  });
  return s + '</DL><p>\n';
}
function exportJson() {
  return JSON.stringify({ app: 'bookmarks', version: 1, exportedAt: new Date().toISOString(),
    bookmarks: items.map(it => ({ url: it.url, title: it.title, description: it.desc || '', note: it.note || '',
      tags: it.tags || [], created: it.created, updated: it.updated, toRead: !!it.toRead, archived: !!it.archived })) }, null, 2);
}
function downloadFile(name, text, type) {
  const blob = new Blob([text], { type: type });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a'); a.href = url; a.download = name;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1500);
}

function renderIoPanel() {
  ioMount.innerHTML = '';
  if (!ioOpen) return;
  const p = document.createElement('div'); p.className = 'io-panel';
  p.innerHTML =
    '<button class="io-close" id="ioClose" aria-label="Close">×</button>' +
    '<div class="io-sec">' +
      '<h2>Import bookmarks</h2>' +
      '<p class="io-sub">Bring in your existing browser bookmarks (an exported .html file) or a backup (.json). ' +
      'Titles, tags (folders become tags), and original saved dates are preserved; anything already saved is skipped.</p>' +
      '<div class="io-controls io-file">' +
        '<label>Choose a file…<input id="ioFile" type="file" accept=".html,.htm,.json" hidden></label>' +
        '<button id="ioSample">Load a sample browser export</button>' +
      '</div>' +
      '<div class="io-result" id="ioImportResult"></div>' +
    '</div>' +
    '<div class="io-sec">' +
      '<h2>Export bookmarks</h2>' +
      '<p class="io-sub">Save all your bookmarks to a file — titles, tags, and original saved dates preserved. ' +
      'The bookmarks file re-imports into browsers; the full backup also keeps notes, descriptions, and read/archive state.</p>' +
      '<div class="io-controls">' +
        '<button class="primary" id="ioExpHtml">Export bookmarks file (HTML)</button>' +
        '<button id="ioExpJson">Export full backup (JSON)</button>' +
      '</div>' +
      '<div class="io-result" id="ioExportResult"></div>' +
    '</div>';
  ioMount.appendChild(p);

  p.querySelector('#ioClose').addEventListener('click', () => { ioOpen = false; renderIoPanel(); });

  const result = p.querySelector('#ioImportResult');
  function showImportPreview(records, sourceLabel) {
    const dupCount = records.filter(r => { const u = normalise(r.url); return u && items.some(x => x.key === keyOf(u)); }).length;
    const okCount = records.length - dupCount;
    result.innerHTML = '';
    const summary = document.createElement('div');
    summary.textContent = 'Found ' + records.length + ' bookmark' + (records.length === 1 ? '' : 's') + ' in ' + sourceLabel +
      ' — ' + okCount + ' new, ' + dupCount + ' already saved.';
    result.appendChild(summary);
    const list = document.createElement('div'); list.className = 'io-preview-list';
    records.slice(0, 12).forEach(function (r) {
      const row = document.createElement('div'); row.className = 'r';
      const dt = new Date(r.created).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
      row.innerHTML = '<strong></strong> <span class="meta"></span>';
      row.querySelector('strong').textContent = r.title || r.url;
      row.querySelector('.meta').textContent = ' — saved ' + dt + (r.tags && r.tags.length ? ' · ' + r.tags.join(', ') : '');
      list.appendChild(row);
    });
    if (records.length > 12) { const m = document.createElement('div'); m.className = 'r meta'; m.textContent = '…and ' + (records.length - 12) + ' more'; list.appendChild(m); }
    result.appendChild(list);
    const go = document.createElement('div'); go.className = 'io-controls'; go.style.marginTop = '10px';
    const btn = document.createElement('button'); btn.className = 'primary'; btn.textContent = 'Import ' + okCount + ' new bookmark' + (okCount === 1 ? '' : 's');
    btn.disabled = okCount === 0;
    btn.addEventListener('click', function () {
      const res = importRecords(records);
      result.innerHTML = 'Imported ' + res.added + ' new bookmark' + (res.added === 1 ? '' : 's') +
        (res.dup ? ' (' + res.dup + ' already saved, skipped)' : '') + (res.bad ? ' (' + res.bad + ' unreadable, skipped)' : '') + '.';
      currentView = 'all'; search.value = ''; redraw();
    });
    go.appendChild(btn); result.appendChild(go);
  }

  p.querySelector('#ioFile').addEventListener('change', function (e) {
    const file = e.target.files[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = function () {
      try { showImportPreview(parseImport(reader.result, file.name), file.name); }
      catch (err) { result.textContent = 'Sorry, that file could not be read as bookmarks.'; }
    };
    reader.readAsText(file);
  });
  p.querySelector('#ioSample').addEventListener('click', function () {
    fetch('sample-bookmarks.html').then(r => r.text()).then(function (txt) {
      showImportPreview(parseImport(txt, 'the sample browser export'), 'the sample browser export');
    }).catch(() => { result.textContent = 'Could not load the sample here.'; });
  });

  const expRes = p.querySelector('#ioExportResult');
  function showExport(name, text, type) {
    downloadFile(name, text, type);
    expRes.innerHTML = 'Downloaded <strong>' + name + '</strong> (' + items.length + ' bookmarks). Preview:';
    const ta = document.createElement('textarea'); ta.className = 'io-text'; ta.readOnly = true; ta.value = text.slice(0, 4000);
    expRes.appendChild(ta);
  }
  p.querySelector('#ioExpHtml').addEventListener('click', () => showExport('bookmarks.html', exportHtml(), 'text/html'));
  p.querySelector('#ioExpJson').addEventListener('click', () => showExport('bookmarks-backup.json', exportJson(), 'application/json'));
}
ioBtn.addEventListener('click', function () { ioOpen = !ioOpen; renderIoPanel(); });

