'use strict';
// Import/export (SCN-019). Parses browser bookmark HTML (Netscape format) and our
// JSON backup; generates a browser-compatible HTML file and a full JSON backup.
const { parse } = require('node-html-parser');
const { cleanTag, uniq } = require('./urlutil');

function attr(node, name) {
  // Netscape files use uppercase attribute names; be tolerant.
  const a = node.attributes || {};
  const keys = Object.keys(a);
  const hit = keys.find(k => k.toLowerCase() === name.toLowerCase());
  return hit ? a[hit] : undefined;
}

function parseNetscape(html) {
  const root = parse(html, { lowerCaseTagName: true, comment: false });
  const out = [];
  function walk(dl, path) {
    dl.childNodes.forEach(node => {
      if (!node.tagName || node.tagName.toLowerCase() !== 'dt') return;
      const h3 = node.childNodes.find(n => n.tagName && n.tagName.toLowerCase() === 'h3');
      if (h3) {
        const name = h3.text.trim();
        let sub = node.childNodes.find(n => n.tagName && n.tagName.toLowerCase() === 'dl');
        if (!sub) {
          // The DL may be the DT's next sibling.
          const sibs = node.parentNode.childNodes;
          const idx = sibs.indexOf(node);
          for (let j = idx + 1; j < sibs.length; j++) {
            const s = sibs[j];
            if (s.tagName && s.tagName.toLowerCase() === 'dl') { sub = s; break; }
            if (s.tagName && s.tagName.toLowerCase() === 'dt') break;
          }
        }
        if (sub) walk(sub, path.concat(name));
      } else {
        const a = node.childNodes.find(n => n.tagName && n.tagName.toLowerCase() === 'a');
        if (a && attr(a, 'href')) {
          const add = attr(a, 'add_date');
          const tagAttr = (attr(a, 'tags') || '').split(',');
          out.push({
            url: attr(a, 'href'),
            title: a.text.trim(),
            created: add ? parseInt(add, 10) * 1000 : Date.now(),
            tags: uniq(path.concat(tagAttr).map(cleanTag).filter(Boolean)),
            description: '', note: '', toRead: false, archived: false
          });
        }
      }
    });
  }
  const top = root.querySelector('dl');
  if (top) walk(top, []);
  return out;
}

function parseImport(text) {
  const t = (text || '').trim();
  if (!t) return [];
  if (t[0] === '{' || t[0] === '[') {
    const data = JSON.parse(t);
    const arr = Array.isArray(data) ? data : (data.bookmarks || []);
    return arr.map(r => ({
      url: r.url,
      title: r.title || '',
      created: r.created || Date.now(),
      updated: r.updated,
      tags: uniq((r.tags || []).map(cleanTag).filter(Boolean)),
      description: r.description || '',
      note: r.note || '',
      toRead: !!r.toRead,
      archived: !!r.archived
    }));
  }
  return parseNetscape(text);
}

function esc(s) {
  return (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function toNetscape(bookmarks) {
  let s = '<!DOCTYPE NETSCAPE-Bookmark-file-1>\n' +
    '<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">\n' +
    '<TITLE>Bookmarks</TITLE>\n<H1>Bookmarks</H1>\n<DL><p>\n';
  bookmarks.forEach(b => {
    const dt = Math.floor((b.created || Date.now()) / 1000);
    s += '    <DT><A HREF="' + esc(b.url) + '" ADD_DATE="' + dt + '"' +
      (b.tags && b.tags.length ? ' TAGS="' + esc(b.tags.join(',')) + '"' : '') +
      '>' + esc(b.title) + '</A>\n';
  });
  return s + '</DL><p>\n';
}

function toJson(bookmarks) {
  return JSON.stringify({
    app: 'calm-bookmarks', version: 1, exportedAt: new Date().toISOString(),
    bookmarks: bookmarks.map(b => ({
      url: b.url, title: b.title, description: b.description || '', note: b.note || '',
      tags: b.tags || [], created: b.created, updated: b.updated,
      toRead: !!b.toRead, archived: !!b.archived
    }))
  }, null, 2);
}

module.exports = { parseImport, parseNetscape, toNetscape, toJson };

