    b.copies.ia = r.ok ? { url: r.url, when: r.when } : null;
    store.persist();
    return res.json({ ok: r.ok, copies: b.copies });
  }
  b.copies.local = await makeSnapshot(b.url, b.id);
  store.persist();
  res.json({ ok: b.copies.local.status === 'ok', copies: b.copies });
