  --bg: #f7f6f3; --card: #ffffff; --ink: #2b2b2b; --muted: #8a8a82; --line: #e8e6e0;
  --accent: #4a6b57; --accent-soft: #eef2ef; --warm: #fff7e8; --warm-line: #f0dfb8; --danger: #b3261e;
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--ink);
  font: 16px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; -webkit-font-smoothing: antialiased; }
.wrap { max-width: 640px; margin: 0 auto; padding: 40px 20px 90px; }
.head-row { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
header h1 { font-size: 22px; font-weight: 600; margin: 0 0 4px; letter-spacing: -.01em; }
header .sub { margin: 0 0 24px; color: var(--muted); font-size: 14px; }
.head-btns { display: flex; gap: 8px; }
.ghost-btn { border: 1px solid var(--line); background: var(--card); color: var(--muted); font: inherit; font-size: 13px; padding: 7px 12px; border-radius: 9px; cursor: pointer; white-space: nowrap; }
.ghost-btn:hover { border-color: var(--accent); color: var(--accent); }

.saver { background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 14px; display: flex; gap: 10px; box-shadow: 0 1px 2px rgba(0,0,0,.03); }
.saver input { flex: 1; border: none; outline: none; font-size: 15px; padding: 10px 8px; background: transparent; color: var(--ink); }
.saver button { border: none; background: var(--accent); color: #fff; font-size: 14px; font-weight: 600; padding: 0 18px; border-radius: 10px; cursor: pointer; }
.saver button:active { transform: translateY(1px); }
.hint { color: var(--muted); font-size: 13px; margin: 10px 4px 0; min-height: 18px; }
.hint.warn { color: #b5741f; }

.review { margin-top: 14px; background: var(--card); border: 1px solid var(--accent); border-radius: 14px; padding: 18px; box-shadow: 0 6px 20px rgba(0,0,0,.06); animation: rise .24s ease; }
.review .cap { font-size: 12px; color: var(--accent); font-weight: 600; text-transform: uppercase; letter-spacing: .04em; margin-bottom: 12px; }
.review .source { display: flex; align-items: center; gap: 8px; color: var(--muted); font-size: 13px; margin: 8px 0 14px; word-break: break-all; }
.field { margin-bottom: 12px; }
.field label { display: block; font-size: 12px; color: var(--muted); margin-bottom: 4px; }
.field input, .field textarea { width: 100%; border: 1px solid var(--line); border-radius: 9px; padding: 9px 11px; font: inherit; font-size: 14px; color: var(--ink); background: #fdfdfc; outline: none; resize: vertical; }
.field input:focus, .field textarea:focus { border-color: var(--accent); }
.preview-img { height: 140px; border-radius: 10px; margin: 0 0 12px; background-size: cover; background-position: center; position: relative; display: flex; align-items: flex-end; color: #fff; }
.preview-img .pv-title { position: relative; z-index: 1; padding: 12px 14px; font-size: 14px; font-weight: 600; text-shadow: 0 1px 3px rgba(0,0,0,.4); }
.preview-img::after { content: ""; position: absolute; inset: 0; border-radius: 10px; background: linear-gradient(to top, rgba(0,0,0,.35), rgba(0,0,0,0) 55%); }
.md-toolbar { display: flex; gap: 6px; margin-bottom: 6px; }
.md-btn { border: 1px solid var(--line); background: #fff; border-radius: 7px; padding: 4px 10px; font-size: 12.5px; cursor: pointer; color: var(--ink); }
.md-btn:hover { border-color: var(--accent); color: var(--accent); }
.note-hint { font-size: 11px; color: var(--muted); margin-top: 5px; }
.note-preview { margin-top: 8px; padding: 10px 12px; border: 1px dashed var(--line); border-radius: 9px; background: #fbfbf9; font-size: 13.5px; color: #4a4a44; }
.note-preview:empty { display: none; }
.note-preview .pv-label { font-size: 10px; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); display: block; margin-bottom: 4px; }
.chk { display: flex; align-items: center; gap: 8px; font-size: 14px; cursor: pointer; margin: 4px 0 14px; }
.chk input { width: 16px; height: 16px; accent-color: var(--accent); cursor: pointer; }
.tag-pick { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; }
.tag-toggle { border: 1px solid var(--line); background: #fff; color: var(--muted); font: inherit; font-size: 12px; padding: 4px 11px; border-radius: 999px; cursor: pointer; }
.tag-toggle.on { background: var(--accent-soft); color: var(--accent); border-color: var(--accent-soft); font-weight: 600; }
.tag-input { width: 100%; border: 1px solid var(--line); border-radius: 9px; padding: 9px 11px; font: inherit; font-size: 14px; outline: none; background: #fdfdfc; }
.tag-input:focus { border-color: var(--accent); }
.actions { display: flex; gap: 8px; margin-top: 6px; }
.btn-primary { border: none; background: var(--accent); color: #fff; font-weight: 600; font-size: 14px; padding: 9px 18px; border-radius: 10px; cursor: pointer; }
.btn-ghost { border: 1px solid var(--line); background: transparent; color: var(--muted); font-size: 14px; padding: 9px 16px; border-radius: 10px; cursor: pointer; }

.views { margin-top: 28px; display: flex; gap: 6px; background: #efece5; padding: 4px; border-radius: 12px; }
.view-tab { flex: 1; border: none; background: transparent; color: var(--muted); font: inherit; font-size: 14px; font-weight: 600; padding: 8px 10px; border-radius: 9px; cursor: pointer; }
.view-tab.on { background: var(--card); color: var(--ink); box-shadow: 0 1px 2px rgba(0,0,0,.06); }

.searchbar { margin-top: 16px; display: flex; align-items: center; gap: 8px; background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 8px 12px; }
.searchbar .mag { color: var(--muted); font-size: 18px; }
.searchbar input { flex: 1; border: none; outline: none; background: transparent; font: inherit; font-size: 15px; color: var(--ink); }
.searchbar .clear { border: none; background: transparent; color: var(--muted); font-size: 18px; cursor: pointer; visibility: hidden; }
.searchbar .clear.show { visibility: visible; }
.save-search { border: 1px solid var(--line); background: transparent; color: var(--muted); font: inherit; font-size: 12.5px; padding: 5px 10px; border-radius: 8px; cursor: pointer; white-space: nowrap; }
.save-search:hover { border-color: var(--accent); color: var(--accent); }

.saved-strip { margin-top: 12px; display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.saved-strip .lead { font-size: 12px; color: var(--muted); }
.saved-chip { display: inline-flex; align-items: center; gap: 6px; background: var(--card); border: 1px solid var(--line); border-radius: 999px; padding: 5px 6px 5px 12px; font-size: 12.5px; }
.saved-chip .name { cursor: pointer; }
.saved-chip .name:hover { color: var(--accent); }
.saved-chip .rm { border: none; background: none; color: var(--muted); cursor: pointer; font-size: 14px; padding: 0 4px; }
.save-form { margin-top: 12px; display: flex; gap: 6px; flex-wrap: wrap; align-items: center; background: var(--accent-soft); border-radius: 10px; padding: 10px 12px; }
.save-form .lbl { font-size: 12.5px; color: var(--accent); }
.save-form input { border: 1px solid var(--line); border-radius: 8px; padding: 7px 10px; font: inherit; font-size: 13px; min-width: 180px; }
.save-form button { border: none; border-radius: 8px; padding: 7px 12px; font: inherit; font-size: 12.5px; cursor: pointer; }
.save-form .ok { background: var(--accent); color: #fff; } .save-form .no { background: transparent; color: var(--muted); border: 1px solid var(--line); }

.sortbar { margin-top: 12px; display: flex; align-items: center; gap: 8px; justify-content: flex-end; }
.sortbar label { font-size: 12.5px; color: var(--muted); }
.sortbar select, .pref-row select { font: inherit; font-size: 13px; color: var(--ink); background: var(--card); border: 1px solid var(--line); border-radius: 9px; padding: 6px 10px; cursor: pointer; }

.search-count { color: var(--muted); font-size: 12.5px; margin: 12px 4px 0; }
.list { margin-top: 16px; display: flex; flex-direction: column; gap: 12px; }
.empty { text-align: center; color: var(--muted); font-size: 14px; padding: 40px 20px; }
.show-more { width: 100%; margin-top: 4px; border: 1px dashed var(--line); background: var(--card); color: var(--accent); font: inherit; font-size: 13px; padding: 10px; border-radius: 10px; cursor: pointer; }

.item { position: relative; background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 16px 18px; box-shadow: 0 1px 2px rgba(0,0,0,.03); animation: rise .28s ease; transition: box-shadow .2s, border-color .2s, background .4s; }
@keyframes rise { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
.item.flash { border-color: var(--warm-line); background: var(--warm); box-shadow: 0 6px 20px rgba(0,0,0,.06); }
.item.selected { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent) inset; }
.sel { position: absolute; top: 12px; right: 12px; z-index: 2; }
.sel input { width: 18px; height: 18px; accent-color: var(--accent); cursor: pointer; }
.item .card-preview { height: 150px; border-radius: 10px; margin: 0 0 12px; background-size: cover; background-position: center; cursor: pointer; position: relative; display: flex; align-items: flex-end; color: #fff; }
.item .card-preview .pt { position: relative; z-index: 1; padding: 12px 14px; font-size: 14px; font-weight: 600; text-shadow: 0 1px 3px rgba(0,0,0,.4); }
.item .card-preview::after { content: ""; position: absolute; inset: 0; border-radius: 10px; background: linear-gradient(to top, rgba(0,0,0,.32), rgba(0,0,0,0) 55%); }
.status-chip { display: inline-block; font-size: 11px; font-weight: 600; padding: 2px 9px; border-radius: 999px; margin-bottom: 8px; }
.status-chip.read { background: #e7efe9; color: var(--accent); }
.status-chip.archived { background: #efece5; color: #8a7a55; }
.item a.title { font-size: 15px; font-weight: 600; color: var(--ink); word-break: break-word; margin: 0 0 4px; display: block; text-decoration: none; }
.item a.title:hover { color: var(--accent); text-decoration: underline; }
.item .desc { font-size: 13.5px; color: #5f5f58; margin: 0 0 8px; word-break: break-word; }
.item .note { font-size: 13.5px; color: #4a4a44; margin: 0 0 10px; padding: 8px 11px; background: #fbfaf7; border-left: 3px solid var(--accent-soft); border-radius: 0 8px 8px 0; }
.item .note p { margin: 0 0 6px; } .item .note p:last-child { margin: 0; }
.item .note ul { margin: 4px 0; padding-left: 18px; } .item .note a { color: var(--accent); }
.tags { display: flex; flex-wrap: wrap; gap: 6px; margin: 2px 0 4px; }
.tag { display: inline-flex; align-items: center; background: var(--accent-soft); color: var(--accent); font-size: 12px; font-weight: 500; padding: 3px 10px; border-radius: 999px; cursor: pointer; }
.tag:hover { background: #dfe8e2; }
.item .url { font-size: 12.5px; color: var(--accent); word-break: break-all; text-decoration: none; }
.foot { display: flex; align-items: center; justify-content: space-between; margin-top: 10px; }
.source-line { display: flex; align-items: center; gap: 7px; color: var(--muted); font-size: 12px; }
.fav { width: 16px; height: 16px; border-radius: 4px; flex: 0 0 auto; display: inline-flex; align-items: center; justify-content: center; overflow: hidden; background: var(--accent-soft); color: var(--accent); font-size: 10px; font-weight: 700; }
.fav img { width: 16px; height: 16px; display: block; }
.card-dates { font-size: 11.5px; color: var(--muted); margin-top: 8px; }
.copies-line { font-size: 12px; color: var(--muted); margin-top: 6px; display: flex; flex-wrap: wrap; gap: 4px 10px; }
.copies-line a { color: var(--accent); text-decoration: none; } .copies-line a:hover { text-decoration: underline; }
.card-actions { display: flex; gap: 6px; margin-top: 12px; flex-wrap: wrap; }
.act { border: 1px solid var(--line); background: #fff; color: var(--ink); font: inherit; font-size: 12.5px; padding: 6px 12px; border-radius: 8px; cursor: pointer; }
.act:hover { border-color: var(--accent); color: var(--accent); }
.act.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.act.primary:hover { color: #fff; }
.act.danger-text { color: var(--danger); } .act.danger-text:hover { border-color: var(--danger); color: var(--danger); }
.act.danger { background: var(--danger); border-color: var(--danger); color: #fff; } .act.danger:hover { color: #fff; }
.confirm-text { font-size: 12.5px; color: var(--danger); align-self: center; }
.copy-panel { margin-top: 10px; border: 1px solid var(--line); border-radius: 10px; padding: 12px; background: #fbfbf9; }
.copy-panel .cp-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; padding: 6px 0; }
.copy-panel .cp-row + .cp-row { border-top: 1px solid var(--line); }
.copy-panel .cp-label { font-size: 13px; font-weight: 600; min-width: 130px; }
.copy-panel .cp-status { font-size: 12.5px; color: var(--muted); }
.copy-panel .cp-note { font-size: 11px; color: var(--muted); margin-top: 8px; }

.bulkbar { position: sticky; top: 8px; z-index: 5; background: var(--accent); color: #fff; border-radius: 12px; padding: 12px 14px; margin: 16px 0; box-shadow: 0 6px 20px rgba(0,0,0,.12); }
.bulk-row1 { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; font-size: 13.5px; }
.bulk-row1 .link { color: #fff; text-decoration: underline; background: none; border: none; cursor: pointer; font: inherit; opacity: .9; }
.bulk-actions { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 10px; }
.bulk-btn { border: 1px solid rgba(255,255,255,.5); background: rgba(255,255,255,.12); color: #fff; font: inherit; font-size: 12.5px; padding: 6px 12px; border-radius: 8px; cursor: pointer; }
.bulk-btn.danger { border-color: #ffd9d4; background: #d3402f; }
.bulk-form { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; margin-top: 10px; }
.bulk-form input { border: none; border-radius: 8px; padding: 7px 10px; font: inherit; font-size: 13px; min-width: 160px; }
.bulk-note { font-size: 12px; opacity: .9; }

.panel { background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 18px; margin-bottom: 20px; box-shadow: 0 4px 16px rgba(0,0,0,.05); }
.panel h2 { font-size: 14px; margin: 0 0 6px; }
.panel .close { float: right; border: none; background: none; color: var(--muted); font-size: 18px; cursor: pointer; }
.io-sec { padding: 12px 0; } .io-sec + .io-sec { border-top: 1px solid var(--line); }
.io-sub { font-size: 12.5px; color: var(--muted); margin: 0 0 10px; }
.io-controls { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.io-controls button, .io-controls label { border: 1px solid var(--line); background: #fff; color: var(--ink); font: inherit; font-size: 13px; padding: 7px 12px; border-radius: 9px; cursor: pointer; }
.io-controls button.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.io-result { margin-top: 12px; font-size: 13px; }
.io-list { margin-top: 8px; padding: 10px 12px; background: #fbfbf9; border: 1px solid var(--line); border-radius: 9px; max-height: 180px; overflow: auto; font-size: 12.5px; }
.io-list .r { padding: 3px 0; } .io-list .meta { color: var(--muted); }
.io-text { width: 100%; margin-top: 10px; height: 140px; font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 11.5px; border: 1px solid var(--line); border-radius: 9px; padding: 10px; background: #fbfbf9; }
.pref-grid { display: flex; flex-direction: column; gap: 14px; }
.pref-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.pref-row .desc { font-size: 11.5px; color: var(--muted); }

