// ---- Review / edit panel ------------------------------------------------
function draftFrom(b) { return { id: b.id, url: b.url, host: b.host, title: b.title, description: b.description, note: b.note, tags: (b.tags || []).slice(), toRead: b.toRead, previewImage: b.previewImage, favicon: b.favicon }; }

