    let out = btn.dataset.md === 'bold' ? '**' + selTxt + '**' : btn.dataset.md === 'italic' ? '*' + selTxt + '*' : (s > 0 && v[s - 1] !== '\n' ? '\n' : '') + '- ' + selTxt;
    fNote.value = v.slice(0, s) + out + v.slice(e); fNote.focus(); paintNote();
